"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[7035],{1526(n,e,a){a.r(e),a.d(e,{assets:()=>p,contentTitle:()=>c,default:()=>h,frontMatter:()=>r,metadata:()=>t,toc:()=>d});const t=JSON.parse('{"id":"part5-deep-learning-and-llms/cnn-architecture","title":"CNNs \u2014 Part 2: Feature Maps, Pooling, and Architecture","description":"This tutorial continues convolution in the way it\u2019s actually used inside CNNs: multi-channel inputs, multiple filters \u2192 feature maps, bias + activation, pooling / strided conv, and the two-stage CNN (conv feature extr...","source":"@site/docs/part5-deep-learning-and-llms/05-cnn-architecture.mdx","sourceDirName":"part5-deep-learning-and-llms","slug":"/part5-deep-learning-and-llms/05-cnn-architecture","permalink":"/tutorials/part5-deep-learning-and-llms/05-cnn-architecture","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":5,"frontMatter":{"title":"CNNs \u2014 Part 2: Feature Maps, Pooling, and Architecture","slug":"/part5-deep-learning-and-llms/05-cnn-architecture","description":"This tutorial continues convolution in the way it\u2019s actually used inside CNNs: multi-channel inputs, multiple filters \u2192 feature maps, bias + activation, pooling / strided conv, and the two-stage CNN (conv feature extr...","sidebar_label":"5. CNN architecture","pagination_label":"5. CNN architecture","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"4. CNN convolution","permalink":"/tutorials/part5-deep-learning-and-llms/04-cnn-convolution"},"next":{"title":"6. CNN PyTorch implementation","permalink":"/tutorials/part5-deep-learning-and-llms/06-cnn-pytorch-implementation"}}');var i=a(4848),o=a(8453),s=a(8172);const l=JSON.parse('{"sourcePath":"part5-deep-learning-and-llms/05-cnn-architecture.html","route":"/part5-deep-learning-and-llms/05-cnn-architecture","kind":"chapter","partId":"part5","partLabel":"Part V - Deep Learning & Large Language Models","accent":"coral","heading":"CNNs \u2014 Part 2: From Color Images to Feature Maps, Pooling, and Full CNN Architecture","title":"CNNs \u2014 Part 2: Feature Maps, Pooling, and Architecture","description":"This tutorial continues convolution in the way it\u2019s actually used inside CNNs: multi-channel inputs, multiple filters \u2192 feature maps, bias + activation, pooling / strided conv, and the two-stage CNN (conv feature extr...","readingMinutes":9,"bodyClass":"","normalizeMath":false,"toc":[{"id":"1-convolution-with-color-images-add-the-channel-dimension","label":"1) Convolution with color images: add the channel dimension"},{"id":"2-multiple-filters-solve-the-uniformity-problem","label":"2) Multiple filters solve the uniformity problem"},{"id":"3-full-convolution-in-cnn-form-shapes-equation","label":"3) Full convolution in CNN form: shapes + equation"},{"id":"4-a-convolution-layer-convolution-bias-activation","label":"4) A convolution layer = convolution + bias + activation"},{"id":"5-why-cnns-are-efficient-parameter-sharing-vs-dense-explosion","label":"5) Why CNNs are efficient: parameter sharing vs dense explosion"},{"id":"6-a-typical-cnn-has-two-stages","label":"6) A typical CNN has two stages"},{"id":"7-pooling-downsampling-by-summarizing-local-neighborhoods","label":"7) Pooling: downsampling by summarizing local neighborhoods"},{"id":"8-why-pooling-helps-translation-invariance","label":"8) Why pooling helps: translation invariance"},{"id":"9-conv-pooling-creates-hierarchical-feature-learning","label":"9) Conv + pooling creates hierarchical feature learning"},{"id":"10-strided-convolution-as-an-alternative-to-pooling","label":"10) Strided convolution as an alternative to pooling"},{"id":"11-flatten-vs-global-max-pooling-handling-variable-image-sizes","label":"11) Flatten vs global max pooling (handling variable image sizes)"},{"id":"12-a-modern-cnn-blueprint-as-summarized-in-the-transcript","label":"12) A modern CNN blueprint (as summarized in the transcript)"},{"id":"local-visuals-and-source-credits","label":"Local visuals and source credits"}],"html":"<div class=\\"wrap\\">\\n    <header>\\n      \\n      <p>\\n        This tutorial continues convolution in the way it\u2019s actually used inside CNNs:\\n        <span class=\\"pill\\">multi-channel</span> inputs,\\n        <span class=\\"pill\\">multiple filters \u2192 feature maps</span>,\\n        <span class=\\"pill\\">bias + activation</span>,\\n        <span class=\\"pill\\">pooling / strided conv</span>,\\n        and the <span class=\\"pill\\">two-stage CNN</span> (conv feature extractor \u2192 dense predictor).\\n      </p>\\n\\n      <div class=\\"chips\\">\\n        <span class=\\"chip\\">Input: H\xd7W\xd7C</span>\\n        <span class=\\"chip\\">Weights: C_in\xd7K\xd7K\xd7C_out</span>\\n        <span class=\\"chip\\">Output: H\xd7W\xd7C_out</span>\\n        <span class=\\"chip\\">Feature maps (channels)</span>\\n        <span class=\\"chip\\">Pooling + translation invariance</span>\\n        <span class=\\"chip\\">Strided convolution</span>\\n        <span class=\\"chip\\">Global max pooling</span>\\n      </div>\\n\\n      <nav>\\n        <a href=\\"#color\\">Color images &amp; 3D kernels</a>\\n        <a href=\\"#featuremaps\\">Multiple filters \u2192 feature maps</a>\\n        <a href=\\"#fullconv\\">Full conv formula + shapes</a>\\n        <a href=\\"#layer\\">Conv layer = conv + bias + activation</a>\\n        <a href=\\"#params\\">Parameter savings vs dense</a>\\n        <a href=\\"#cnnarch\\">Two-stage CNN architecture</a>\\n        <a href=\\"#pool\\">Pooling (max/avg) mechanics</a>\\n        <a href=\\"#invariance\\">Why pooling works: translation invariance</a>\\n        <a href=\\"#hierarchy\\">Conv+pool \u2192 hierarchical features</a>\\n        <a href=\\"#stride\\">Strided conv as pooling alternative</a>\\n        <a href=\\"#global\\">Flatten vs global max pooling</a>\\n        <a href=\\"#end\\">Putting it all together</a>\\n        <a href=\\"#credits\\">Local visuals and credits</a>\\n      </nav>\\n    </header>\\n\\n    <section id=\\"color\\">\\n      <h2 id=\\"1-convolution-with-color-images-add-the-channel-dimension\\">1) Convolution with color images: add the channel dimension</h2>\\n\\n      <p>\\n        Real CNNs usually take <b>color images</b>. A color image is a 3D object:\\n        \\\\[\\n          X \\\\in \\\\mathbb{R}^{H \\\\times W \\\\times C_{\\\\text{in}}}\\n        \\\\]\\n        where \\\\(C_{\\\\text{in}}=3\\\\) for RGB.\\n      </p>\\n\\n      <p>\\n        To convolve a color image, you use a <b>3D kernel</b> (a \u201csmall box\u201d) that spans all input channels:\\n        \\\\[\\n          W \\\\in \\\\mathbb{R}^{K \\\\times K \\\\times C_{\\\\text{in}}}\\n        \\\\]\\n      </p>\\n\\n      <p>\\n        Mechanically, it\u2019s the same \u201cmultiply + add\u201d you already know\u2014just with an extra sum over channels:\\n        you sum over <b>height</b>, <b>width</b>, and <b>channels</b>.\\n      </p>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Color pattern-finder intuition:</b> a 3D filter can match \u201cred circles\u201d differently from \u201cblue circles\u201d\\n          because it has separate weights for each channel.\\n        </p>\\n      </div>\\n\\n      <figure>\\n        <img alt=\\"RGB channels split (conceptual)\\" src=\\"/tutorials/images/external/Rgb_channels_separate-66f58fb11f-fallback.svg\\">\\n        <figcaption>\\n          Local book diagram of separated RGB channels. Technical reference:\\n          <a href=\\"https://docs.opencv.org/4.x/de/d25/imgproc_color_conversions.html\\" target=\\"_blank\\" rel=\\"noopener\\">OpenCV color conversions</a>.\\n        </figcaption>\\n      </figure>\\n\\n      <p class=\\"muted\\">\\n        If you convolve a 3D image with a single 3D kernel and sum across channels, the output is 2D\\n        (the channel dimension \u201cdots out\u201d). That\u2019s fine for one filter\u2014but it breaks the \u201cstack layers\u201d uniformity.\\n      </p>\\n    </section>\\n\\n    <section id=\\"featuremaps\\">\\n      <h2 id=\\"2-multiple-filters-solve-the-uniformity-problem\\">2) Multiple filters solve the uniformity problem</h2>\\n\\n      <p>\\n        A single filter finds a single feature. But images contain many features\u2014edges, corners, textures, eyes, noses, etc.\\n        So CNNs use <b>many filters</b>.\\n      </p>\\n\\n      <p>\\n        If you apply two different filters \\\\(W^{(1)}\\\\) and \\\\(W^{(2)}\\\\) to the same input \\\\(X\\\\), you get two 2D outputs:\\n        \\\\[\\n          B^{(1)} = X \\\\star W^{(1)}, \\\\quad B^{(2)} = X \\\\star W^{(2)}\\n        \\\\]\\n        Stack them and you get a 3D output again:\\n        \\\\[\\n          B = \\\\text{stack}\\\\left(B^{(1)}, B^{(2)}, \\\\ldots\\\\right) \\\\in \\\\mathbb{R}^{H \\\\times W \\\\times C_{\\\\text{out}}}\\n        \\\\]\\n      </p>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Terminology shift:</b> after the first layer, the last dimension is no longer \u201ccolor\u201d.\\n          It\u2019s the number of <b>channels</b> or <b>feature maps</b> (one map per learned feature).\\n        </p>\\n      </div>\\n\\n      <figure>\\n        <img alt=\\"Feature map visualization from a CNN layer (conceptual)\\" src=\\"/tutorials/images/external/Typical_cnn-46df08c8b8-fallback.svg\\">\\n        <figcaption>\\n          Local book diagram showing stacks of CNN feature maps. Historical reference:\\n          <a href=\\"https://doi.org/10.1109/5.726791\\" target=\\"_blank\\" rel=\\"noopener\\">LeCun et al., 1998</a>.\\n        </figcaption>\\n      </figure>\\n    </section>\\n\\n    <section id=\\"fullconv\\">\\n      <h2 id=\\"3-full-convolution-in-cnn-form-shapes-equation\\">3) Full convolution in CNN form: shapes + equation</h2>\\n\\n      <h3 id=\\"shapes-used-in-this-lecture\\">Shapes used in this lecture</h3>\\n      <ul>\\n        <li>Input: \\\\(X \\\\in \\\\mathbb{R}^{H \\\\times W \\\\times C_1}\\\\)</li>\\n        <li>Weights: \\\\(W \\\\in \\\\mathbb{R}^{C_1 \\\\times K \\\\times K \\\\times C_2}\\\\)</li>\\n        <li>Output (same mode): \\\\(Y \\\\in \\\\mathbb{R}^{H \\\\times W \\\\times C_2}\\\\)</li>\\n      </ul>\\n\\n      <p class=\\"muted\\">\\n        Many frameworks store weights as \\\\((C_2, C_1, K, K)\\\\). The transcript\u2019s shape is equivalent\u2014just a different axis order.\\n      </p>\\n\\n      <h3 id=\\"index-form-same-mode-stride-1-deep-learning-style-correlation\\">Index form (same-mode, stride 1; \u201cdeep learning style\u201d correlation)</h3>\\n      <p>\\n        Let \\\\(Y_{i,j,c}\\\\) be the output at spatial position \\\\((i,j)\\\\) and output channel \\\\(c\\\\) (a feature map).\\n        Then:\\n      </p>\\n\\n      <p>\\n        \\\\[\\n          Y_{i,j,c} = \\\\sum_{c\'=1}^{C_1}\\\\sum_{u=0}^{K-1}\\\\sum_{v=0}^{K-1}\\n          X_{i+u-\\\\Delta,\\\\;j+v-\\\\Delta,\\\\;c\'} \\\\; W_{c\',u,v,c}\\n        \\\\]\\n      </p>\\n\\n      <p class=\\"muted\\">\\n        Here \\\\(\\\\Delta=\\\\lfloor K/2 \\\\rfloor\\\\) corresponds to \u201csame\u201d padding for odd \\\\(K\\\\) (conceptually: zeros around the image).\\n      </p>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Concept:</b> each output channel \\\\(c\\\\) corresponds to one filter (one learned feature).\\n          The output tensor is a stack of feature maps.\\n        </p>\\n      </div>\\n\\n      <figure>\\n        <img alt=\\"Convolution arithmetic illustration showing shapes\\" src=\\"/tutorials/images/external/Convolution_arithmetic_padding_strides-939a950445-fallback.svg\\">\\n        <figcaption>\\n          Local book diagram of convolution arithmetic. Technical reference:\\n          <a href=\\"https://arxiv.org/abs/1603.07285\\" target=\\"_blank\\" rel=\\"noopener\\">Dumoulin and Visin</a>.\\n        </figcaption>\\n      </figure>\\n    </section>\\n\\n    <section id=\\"layer\\">\\n      <h2 id=\\"4-a-convolution-layer-convolution-bias-activation\\">4) A convolution layer = convolution + bias + activation</h2>\\n\\n      <p>\\n        A CNN layer mirrors a dense layer idea:\\n      </p>\\n      <p>\\n        \\\\[\\n          \\\\text{Dense: } z = Wx + b,\\\\quad a = \\\\sigma(z)\\n        \\\\]\\n      </p>\\n      <p>\\n        For convolution:\\n      </p>\\n      <p>\\n        \\\\[\\n          Z = X \\\\star W + b,\\\\quad A = \\\\sigma(Z)\\n        \\\\]\\n      </p>\\n\\n      <h3 id=\\"bias-shape-and-broadcasting\\">Bias shape and broadcasting</h3>\\n      <p>\\n        The convolution output has shape \\\\(H \\\\times W \\\\times C_2\\\\).\\n        The bias term is a <b>vector</b> \\\\(b \\\\in \\\\mathbb{R}^{C_2}\\\\): one scalar per feature map.\\n        In code, broadcasting adds \\\\(b_c\\\\) to every spatial location \\\\((i,j)\\\\) in that feature map.\\n      </p>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Broadcasting intuition:</b> bias is \u201cper-channel\u201d, not \u201cper-pixel\u201d.\\n          It\u2019s the same idea as dense layers (one bias per output unit), just expanded across the grid.\\n        </p>\\n      </div>\\n\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 conv layer with bias + activation (PyTorch)</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>import torch\\nimport torch.nn as nn\\n\\n# Example: Cin=3 (RGB), Cout=16 feature maps, 3x3 kernels\\nlayer = nn.Sequential(\\n    nn.Conv2d(in_channels=3, out_channels=16, kernel_size=3, padding=1, bias=True),  # \\"same\\" for 3x3\\n    nn.ReLU()\\n)\\n\\nx = torch.randn(8, 3, 32, 32)   # NCHW: batch=8, channels=3, H=W=32\\ny = layer(x)\\nprint(y.shape)  # (8, 16, 32, 32)</code></pre>\\n      </div>\\n\\n      <p class=\\"muted\\">\\n        Notice PyTorch uses NCHW ordering: \\\\((N, C, H, W)\\\\).\\n        The \u201cchannels\u201d here are feature maps after the first layer.\\n      </p>\\n    </section>\\n\\n    <section id=\\"params\\">\\n      <h2 id=\\"5-why-cnns-are-efficient-parameter-sharing-vs-dense-explosion\\">5) Why CNNs are efficient: parameter sharing vs dense explosion</h2>\\n\\n      <p>\\n        Parameter sharing means one small kernel is reused across the entire image.\\n        That dramatically reduces parameter count compared to flattening and using a dense layer.\\n      </p>\\n\\n      <h3 id=\\"worked-parameter-comparison-from-the-transcript\\">Worked parameter comparison (from the transcript)</h3>\\n      <p>\\n        Input image: \\\\(32 \\\\times 32 \\\\times 3\\\\). Kernel: \\\\(3 \\\\times 5 \\\\times 5 \\\\times 64\\\\) (64 output feature maps).\\n        Using valid convolution, output spatial size is \\\\((32-5+1)\\\\times(32-5+1)=28\\\\times 28\\\\).\\n        So output is \\\\(28\\\\times 28\\\\times 64\\\\).\\n      </p>\\n\\n      <div class=\\"grid two\\">\\n        <div class=\\"callout\\">\\n          <p style=\\"margin:0;\\">\\n            <b>Convolution parameters</b><br>\\n            \\\\(3 \\\\cdot 5 \\\\cdot 5 \\\\cdot 64 = 4800\\\\)\\n          </p>\\n        </div>\\n        <div class=\\"callout\\">\\n          <p style=\\"margin:0;\\">\\n            <b>Dense parameters (flattened)</b><br>\\n            input: \\\\(32\\\\cdot 32\\\\cdot 3 = 3072\\\\)<br>\\n            output: \\\\(28\\\\cdot 28\\\\cdot 64 = 50176\\\\)<br>\\n            weights: \\\\(3072 \\\\times 50176 \\\\approx 154\\\\) million\\n          </p>\\n        </div>\\n      </div>\\n\\n      <p class=\\"muted\\">\\n        Dense would have ~32,000\xd7 more parameters in this example. This increases memory and compute and can hurt generalization,\\n        because dense must learn separate weights for the \u201csame pattern\u201d at every location.\\n      </p>\\n\\n      <figure>\\n        <img alt=\\"Illustration of local receptive fields and weight sharing in CNNs\\" src=\\"/tutorials/images/external/Conv_layer-42782a549f-fallback.svg\\">\\n        <figcaption>\\n          Local receptive fields / convolution layer concept (Wikimedia Commons):\\n          <a href=\\"https://commons.wikimedia.org/wiki/File:Conv_layer.png\\" target=\\"_blank\\" rel=\\"noopener\\">Conv_layer.png</a>\\n        </figcaption>\\n      </figure>\\n    </section>\\n\\n    <section id=\\"cnnarch\\">\\n      <h2 id=\\"6-a-typical-cnn-has-two-stages\\">6) A typical CNN has two stages</h2>\\n\\n      <p>\\n        CNNs are commonly organized as:\\n      </p>\\n      <ol>\\n        <li>\\n          <b>Convolutional stage</b>: repeated blocks that extract image features\\n          (often <code>Conv \u2192 (Pooling or Stride)</code>).\\n        </li>\\n        <li>\\n          <b>Dense stage</b>: a standard feed-forward network that performs classification/regression on extracted features.\\n        </li>\\n      </ol>\\n\\n      <figure>\\n        <img alt=\\"LeNet-5 architecture diagram (classic CNN archetype)\\" src=\\"/tutorials/images/external/LeNet5-46fbf8dc74-fallback.svg\\">\\n        <figcaption>\\n          Local book diagram of the LeNet-5 pattern. Primary reference:\\n          <a href=\\"https://doi.org/10.1109/5.726791\\" target=\\"_blank\\" rel=\\"noopener\\">LeCun et al., 1998</a>.\\n        </figcaption>\\n      </figure>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Mental model:</b> the conv stage is a feature transformer designed for images.\\n          Once features are extracted, the dense stage handles non-linear prediction (classification/regression).\\n        </p>\\n      </div>\\n    </section>\\n\\n    <section id=\\"pool\\">\\n      <h2 id=\\"7-pooling-downsampling-by-summarizing-local-neighborhoods\\">7) Pooling: downsampling by summarizing local neighborhoods</h2>\\n\\n      <p>\\n        Pooling reduces spatial size (e.g., 100\xd7100 \u2192 50\xd750 with 2\xd72 pooling, stride 2).\\n        Two common types:\\n      </p>\\n      <ul>\\n        <li><b>Max pooling</b>: take the maximum value in each pooling window</li>\\n        <li><b>Average pooling</b>: take the average in each pooling window</li>\\n      </ul>\\n\\n      <h3 id=\\"mechanics-with-the-transcript-s-4-4-example-pool-2-stride-2\\">Mechanics with the transcript\u2019s 4\xd74 example (pool=2, stride=2)</h3>\\n\\n      <div class=\\"grid two\\">\\n        <div>\\n          <p><b>Input</b></p>\\n          <table aria-label=\\"Pooling input 4x4\\">\\n            <tbody><tr><td>1</td><td>2</td><td>3</td><td>4</td></tr>\\n            <tr><td>5</td><td>6</td><td>7</td><td>8</td></tr>\\n            <tr><td>16</td><td>15</td><td>14</td><td>13</td></tr>\\n            <tr><td>12</td><td>11</td><td>10</td><td>9</td></tr>\\n          </tbody></table>\\n        </div>\\n        <div>\\n          <p><b>MaxPool2d(2)</b> output</p>\\n          <table aria-label=\\"Max pooling output 2x2\\">\\n            <tbody><tr><td>6</td><td>8</td></tr>\\n            <tr><td>16</td><td>14</td></tr>\\n          </tbody></table>\\n\\n          <p><b>AvgPool2d(2)</b> output</p>\\n          <table aria-label=\\"Average pooling output 2x2\\">\\n            <tbody><tr><td>3.5</td><td>5.5</td></tr>\\n            <tr><td>13.5</td><td>11.5</td></tr>\\n          </tbody></table>\\n        </div>\\n      </div>\\n\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 max pooling and average pooling (PyTorch)</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>import torch\\nimport torch.nn as nn\\n\\nx = torch.tensor([[[[ 1.,  2.,  3.,  4.],\\n                    [ 5.,  6.,  7.,  8.],\\n                    [16., 15., 14., 13.],\\n                    [12., 11., 10.,  9.]]]])  # shape (N=1, C=1, H=4, W=4)\\n\\nmaxpool = nn.MaxPool2d(kernel_size=2, stride=2)\\navgpool = nn.AvgPool2d(kernel_size=2, stride=2)\\n\\nprint(\\"max:\\\\n\\", maxpool(x)[0,0])\\nprint(\\"avg:\\\\n\\", avgpool(x)[0,0])</code></pre>\\n      </div>\\n\\n      <figure>\\n        <img alt=\\"Max pooling visualization\\" src=\\"/tutorials/images/external/Max_pooling-422a90d58b.png\\">\\n        <figcaption>\\n          Max pooling visualization (Wikimedia Commons):\\n          <a href=\\"https://commons.wikimedia.org/wiki/File:Max_pooling.png\\" target=\\"_blank\\" rel=\\"noopener\\">Max_pooling.png</a>\\n        </figcaption>\\n      </figure>\\n    </section>\\n\\n    <section id=\\"invariance\\">\\n      <h2 id=\\"8-why-pooling-helps-translation-invariance\\">8) Why pooling helps: translation invariance</h2>\\n\\n      <p>\\n        Pooling supports the idea of <b>translation invariance</b>:\\n        we often care that a feature exists somewhere, not exactly where it is.\\n      </p>\\n\\n      <p>\\n        In a small 2\xd72 region, a feature detector output might look like \u201chigh, low, low, low\u201d.\\n        Max pooling returns the high value, preserving \u201cfeature found\u201d while discarding precise location.\\n      </p>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Max pooling intuition:</b> \u201cif the pattern appears anywhere in this window, keep it.\u201d\\n          This often matches what you want for recognition tasks.\\n        </p>\\n      </div>\\n\\n      <p class=\\"muted\\">\\n        Pooling layers also have hyperparameters:\\n        pool size (e.g., 2\xd72) and stride (often 2).\\n        Overlapping pooling (stride 1) exists but is less common in typical modern setups.\\n      </p>\\n    </section>\\n\\n    <section id=\\"hierarchy\\">\\n      <h2 id=\\"9-conv-pooling-creates-hierarchical-feature-learning\\">9) Conv + pooling creates hierarchical feature learning</h2>\\n\\n      <p>\\n        CNNs often repeat the pattern: <b>convolution \u2192 pooling \u2192 convolution \u2192 pooling</b>.\\n        Spatial size decreases, while filters remain small (commonly 3\xd73, 5\xd75, 7\xd77).\\n      </p>\\n\\n      <h3 id=\\"why-small-filters-start-as-tiny-pattern-detectors\\">Why small filters start as \u201ctiny pattern\u201d detectors</h3>\\n      <p>\\n        A 3\xd73 filter covers a tiny fraction of a 32\xd732 image.\\n        After downsampling to 16\xd716, the same 3\xd73 covers a larger fraction of the image;\\n        later it can cover a very large portion (e.g., on 4\xd74).\\n      </p>\\n\\n      <p>\\n        This is one reason CNNs learn features hierarchically:\\n        early layers tend to pick up small patterns (edges/strokes),\\n        later layers pick up larger patterns (parts, then whole objects).\\n      </p>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Two linked effects:</b><br>\\n          1) spatial dimensions shrink<br>\\n          2) fixed-size filters \u201csee\u201d relatively larger areas \u2192 bigger patterns\\n        </p>\\n      </div>\\n\\n      <p class=\\"muted\\">\\n        Yes, shrinking loses spatial detail (\u201cwhere\u201d). But CNNs often compensate by increasing\\n        the number of feature maps (\u201cwhat\u201d) as depth increases.\\n      </p>\\n    </section>\\n\\n    <section id=\\"stride\\">\\n      <h2 id=\\"10-strided-convolution-as-an-alternative-to-pooling\\">10) Strided convolution as an alternative to pooling</h2>\\n\\n      <p>\\n        Pooling isn\u2019t the only downsampling option. Convolution itself can downsample using a <b>stride</b>:\\n        stride tells you how far the sliding window jumps each step.\\n      </p>\\n\\n      <p>\\n        With stride 2, output spatial dimensions are roughly halved\u2014similar to pooling with 2\xd72, stride 2.\\n      </p>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Why skipping pixels can be okay:</b> nearby pixels are often highly correlated in natural images.\\n          Skipping every other pixel still preserves much of the structure while reducing computation.\\n        </p>\\n      </div>\\n\\n      <figure>\\n        <img alt=\\"Convolution with stride illustration\\" src=\\"/tutorials/images/external/Conv_arithmetic_strides-4314c5336a-fallback.svg\\">\\n        <figcaption>\\n          Local book diagram of strided convolution. Technical reference:\\n          <a href=\\"https://arxiv.org/abs/1603.07285\\" target=\\"_blank\\" rel=\\"noopener\\">Dumoulin and Visin</a>.\\n        </figcaption>\\n      </figure>\\n\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 strided conv vs conv+pool (shape comparison)</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>import torch\\nimport torch.nn as nn\\n\\nx = torch.randn(1, 3, 32, 32)\\n\\n# Option A: conv then pool\\nconv = nn.Conv2d(3, 16, kernel_size=3, padding=1)     # keep 32x32\\npool = nn.MaxPool2d(2, stride=2)                      # downsample to 16x16\\ny_a = pool(torch.relu(conv(x)))\\n\\n# Option B: strided conv (downsample directly)\\nconv_s2 = nn.Conv2d(3, 16, kernel_size=3, padding=1, stride=2)\\ny_b = torch.relu(conv_s2(x))\\n\\nprint(\\"conv+pool:\\", y_a.shape)  # (1, 16, 16, 16)\\nprint(\\"stride=2:\\", y_b.shape)   # (1, 16, 16, 16)</code></pre>\\n      </div>\\n\\n      <p class=\\"muted\\">\\n        Both produce the same spatial size here; the difference is where downsampling happens and how parameters are used.\\n      </p>\\n    </section>\\n\\n    <section id=\\"global\\">\\n      <h2 id=\\"11-flatten-vs-global-max-pooling-handling-variable-image-sizes\\">11) Flatten vs global max pooling (handling variable image sizes)</h2>\\n\\n      <p>\\n        The dense stage expects a 1D feature vector. A convolutional output is 3D:\\n        \\\\[\\n          X \\\\in \\\\mathbb{R}^{H \\\\times W \\\\times C}\\n        \\\\]\\n        so a common step is to <b>flatten</b> to a vector of size \\\\(H\\\\cdot W\\\\cdot C\\\\).\\n      </p>\\n\\n      <h3 id=\\"why-flattening-fails-for-variable-image-sizes\\">Why flattening fails for variable image sizes</h3>\\n      <p>\\n        If the network outputs 2\xd72\xd7100 for a 32\xd732 input, flatten gives 400 features.\\n        For a larger 64\xd764 input that becomes 4\xd74\xd7100, flatten gives 1600 features.\\n        A fixed dense layer can\u2019t accept both sizes.\\n      </p>\\n\\n      <h3 id=\\"global-max-pooling-size-independent-output\\">Global max pooling: size-independent output</h3>\\n      <p>\\n        Global max pooling collapses the entire spatial grid:\\n        \\\\[\\n          \\\\text{GMP}(X)_c = \\\\max_{i,j} X_{i,j,c}\\n        \\\\]\\n        producing a vector of size \\\\(C\\\\), regardless of \\\\(H\\\\) and \\\\(W\\\\).\\n      </p>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Interpretation:</b> \u201cI don\u2019t care where the feature appears in the image\u2014if it appears anywhere, keep the strongest evidence.\u201d\\n        </p>\\n      </div>\\n\\n      <figure>\\n        <img alt=\\"Global average pooling diagram (conceptual; same idea applies to global max pooling)\\" src=\\"/tutorials/images/external/GlobalAveragePooling-ea08b562e2-fallback.svg\\">\\n        <figcaption>\\n          Local book diagram of global pooling. Primary reference for global average pooling:\\n          <a href=\\"https://arxiv.org/abs/1312.4400\\" target=\\"_blank\\" rel=\\"noopener\\">Lin, Chen, and Yan, <em>Network in Network</em></a>.\\n        </figcaption>\\n      </figure>\\n\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 global max pooling in PyTorch (works for any H\xd7W)</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>import torch\\nimport torch.nn as nn\\n\\ngmp = nn.AdaptiveMaxPool2d((1, 1))  # global max pooling to 1x1\\n\\nx1 = torch.randn(8, 100, 2, 2)     # e.g., from 32x32 after downsampling\\nx2 = torch.randn(8, 100, 4, 4)     # e.g., from 64x64 after downsampling\\n\\ny1 = gmp(x1).squeeze(-1).squeeze(-1)  # shape: (8, 100)\\ny2 = gmp(x2).squeeze(-1).squeeze(-1)  # shape: (8, 100)\\n\\nprint(y1.shape, y2.shape)</code></pre>\\n      </div>\\n\\n      <p class=\\"muted\\">\\n        <b>Note:</b> images can\u2019t be downsampled indefinitely. If the spatial size becomes too small (e.g., 2\xd72),\\n        additional stride-2 operations will fail.\\n      </p>\\n    </section>\\n\\n    <section id=\\"end\\">\\n      <h2 id=\\"12-a-modern-cnn-blueprint-as-summarized-in-the-transcript\\">12) A modern CNN blueprint (as summarized in the transcript)</h2>\\n\\n      <p>\\n        A practical CNN often follows:\\n      </p>\\n\\n      <ol>\\n        <li>\\n          <b>Convolutional stage</b>:\\n          repeated blocks that downsample while increasing channels\\n          <ul>\\n            <li>Option A: <code>Conv \u2192 Pool</code> (repeat)</li>\\n            <li>Option B: <code>Strided Conv</code> (repeat)</li>\\n            <li>Keep filter sizes small (commonly 3\xd73, 5\xd75, 7\xd77)</li>\\n            <li>Increase feature maps with depth (e.g., 32 \u2192 64 \u2192 128 \u2192 ...)</li>\\n          </ul>\\n        </li>\\n        <li>\\n          <b>Bridge</b>:\\n          convert 3D feature maps to 1D features\\n          <ul>\\n            <li>Flatten (<code>view</code>) for fixed-size inputs</li>\\n            <li>or Global pooling for variable-size inputs</li>\\n          </ul>\\n        </li>\\n        <li>\\n          <b>Dense stage</b>:\\n          standard feed-forward layers ending with task-appropriate output\\n          <ul>\\n            <li>Regression: 1 output, identity (no activation)</li>\\n            <li>Binary classification: 1 output, sigmoid</li>\\n            <li>Multi-class (K\u22652): K outputs, softmax (often combined with cross-entropy loss)</li>\\n          </ul>\\n        </li>\\n      </ol>\\n\\n      <div class=\\"codewrap\\">\\n        <div class=\\"codebar\\">\\n          <span class=\\"label\\">python \u2022 reference CNN skeleton (conv stage \u2192 global max pool \u2192 dense)</span>\\n          \\n        </div>\\n<pre class=\\"language-python\\"><code>import torch.nn as nn\\n\\nclass SimpleCNN(nn.Module):\\n    def __init__(self, num_classes=10):\\n        super().__init__()\\n        self.features = nn.Sequential(\\n            nn.Conv2d(3, 32, 3, padding=1), nn.ReLU(),\\n            nn.Conv2d(32, 64, 3, padding=1, stride=2), nn.ReLU(),   # stride downsample\\n            nn.Conv2d(64, 128, 3, padding=1, stride=2), nn.ReLU(),\\n        )\\n        self.gmp = nn.AdaptiveMaxPool2d((1, 1))  # global max pool\\n        self.classifier = nn.Sequential(\\n            nn.Linear(128, 128), nn.ReLU(),\\n            nn.Linear(128, num_classes)\\n        )\\n\\n    def forward(self, x):\\n        x = self.features(x)               # (N, 128, H\', W\')\\n        x = self.gmp(x).squeeze(-1).squeeze(-1)  # (N, 128)\\n        return self.classifier(x)          # logits\\n\\n# Use with nn.CrossEntropyLoss() for multi-class classification</code></pre>\\n      </div>\\n\\n      <div class=\\"callout\\">\\n        <p style=\\"margin:0;\\">\\n          <b>Big picture:</b> convolution learns feature transformers automatically during training (weights + biases),\\n          just like dense layers\u2014only the tensor shapes and parameter sharing differ.\\n        </p>\\n      </div>\\n    </section>\\n\\n    <section id=\\"credits\\">\\n      <h2 id=\\"local-visuals-and-source-credits\\">Local visuals and source credits</h2>\\n      <ul class=\\"small\\">\\n        <li>RGB channels diagram: local book asset; concept reference: <a href=\\"https://docs.opencv.org/4.x/de/d25/imgproc_color_conversions.html\\" target=\\"_blank\\" rel=\\"noopener\\">OpenCV color conversions</a></li>\\n        <li>CNN feature-map stack: local book asset; historical reference: <a href=\\"https://doi.org/10.1109/5.726791\\" target=\\"_blank\\" rel=\\"noopener\\">LeCun et al., 1998</a></li>\\n        <li>Convolution arithmetic (padding/stride): local book asset; concept reference: <a href=\\"https://arxiv.org/abs/1603.07285\\" target=\\"_blank\\" rel=\\"noopener\\">Dumoulin and Visin</a></li>\\n        <li>Local receptive fields / conv layer concept: <a href=\\"https://commons.wikimedia.org/wiki/File:Conv_layer.png\\" target=\\"_blank\\" rel=\\"noopener\\">Wikimedia Commons</a></li>\\n        <li>LeNet-5 pattern: local book asset; primary reference: <a href=\\"https://doi.org/10.1109/5.726791\\" target=\\"_blank\\" rel=\\"noopener\\">LeCun et al., 1998</a></li>\\n        <li>Max pooling visualization: <a href=\\"https://commons.wikimedia.org/wiki/File:Max_pooling.png\\" target=\\"_blank\\" rel=\\"noopener\\">Wikimedia Commons</a></li>\\n        <li>Stride arithmetic: local book asset; concept reference: <a href=\\"https://arxiv.org/abs/1603.07285\\" target=\\"_blank\\" rel=\\"noopener\\">Dumoulin and Visin</a></li>\\n        <li>Global pooling: local book asset; primary reference: <a href=\\"https://arxiv.org/abs/1312.4400\\" target=\\"_blank\\" rel=\\"noopener\\">Network in Network</a></li>\\n      </ul>\\n\\n      <div class=\\"hr\\"></div>\\n      <p class=\\"muted small\\">\\n        This HTML is self-contained in structure: equations render via MathJax CDN, code blocks are readable with copy buttons,\\n        and all displayed visuals are local assets, with source attribution or primary concept references retained where applicable.\\n      </p>\\n    </section>\\n\\n  </div>"}'),r={title:"CNNs \u2014 Part 2: Feature Maps, Pooling, and Architecture",slug:"/part5-deep-learning-and-llms/05-cnn-architecture",description:"This tutorial continues convolution in the way it\u2019s actually used inside CNNs: multi-channel inputs, multiple filters \u2192 feature maps, bias + activation, pooling / strided conv, and the two-stage CNN (conv feature extr...",sidebar_label:"5. CNN architecture",pagination_label:"5. CNN architecture",hide_title:!0,hide_table_of_contents:!0},c=void 0,p={},d=[];function u(n){return(0,i.jsx)(s.A,{content:l})}function h(n={}){const{wrapper:e}={...(0,o.R)(),...n.components};return e?(0,i.jsx)(e,{...n,children:(0,i.jsx)(u,{...n})}):u()}}}]);